'use strict';
// Business word results share one filtered scope across chart, table, sources and exports.
const wrBase={modalContent,handleAction,awToolbar};
function wrScopeIds(task){const v=av('word');return (task.successIds||task.ids||[]).filter(id=>{const d=file(id);return d&&!d.deleted&&auditFileAccess(d).read&&(v.resultScope==='all'||id===v.resultScope)&&(!v.resultFolder||d.space===v.resultFolder.space&&underFolder(d.folder,v.resultFolder.path));});}
function wrAllWords(task){const v=av('word'),scope=new Set(wrScopeIds(task)),query=v.resultQuery.trim().toLowerCase();return (task.result||[]).map(r=>{const docs=(r.docs||[]).filter(id=>scope.has(id)),count=r.byFile?docs.reduce((n,id)=>n+(Number(r.byFile[id])||0),0):Number(r.count)||0;return {...r,docs,count};}).filter(r=>r.docs.length&&r.count>0&&r.word.toLowerCase().includes(query)).sort((a,b)=>b.count-a.count||a.word.localeCompare(b.word,'zh-CN'));}
awWordRows=function(task){const v=av('word');return wrAllWords(task).slice(0,v.top||task.displayTop||task.config.top||30);};
function wrPageFooter(page,pages,count,action){return '<footer class="wr-pagination"><span>共 <strong>'+count+'</strong> '+(action==='wr-source-page'?'份资料':'个词')+'</span><div>'+B('上一页',action,'ghost sm','data-step="-1" '+(page<=1?'disabled':''))+'<span>'+page+' / '+pages+'</span>'+B('下一页',action,'ghost sm','data-step="1" '+(page>=pages?'disabled':''))+'</div></footer>';}
function wrStopButton(word){const pending=(ws('word').pendingStopWords||[]).includes(word);return B(pending?'下次已停用':'加入停用词','aw-stop-word','ghost sm wr-stop','data-word="'+E(word)+'" title="'+(pending?'已加入下次分析的停用词，本次结果保留':'加入停用词，下一次分析使用；本次结果保留')+'" '+(pending?'disabled':''));}
function wrCloud(rows){const max=rows[0]?.count||1;return '<div class="aw-cloud wr-cloud" aria-label="词云，点击词语查看来源">'+rows.map((r,i)=>'<button data-action="word-detail" data-word="'+E(r.word)+'" class="'+(av('word').word===r.word?'is-active':'')+'" title="'+E(r.word)+'：出现 '+r.count+' 次，涉及 '+r.docs.length+' 份资料" style="font-size:'+Math.round(18+28*Math.sqrt(r.count/max))+'px;color:'+['#245dae','#22746a','#716099','#426e87','#886637'][i%5]+';font-weight:'+(i<5?600:400)+'">'+E(r.word)+'</button>').join('')+'</div>';}
awWord=function(task){const v=av('word'),all=wrAllWords(task),rows=awWordRows(task),view=['cloud','frequency'].includes(v.tab)?v.tab:'both',size=20,pages=Math.max(1,Math.ceil(rows.length/size));v.resultPage=Math.max(1,Math.min(v.resultPage,pages));const shown=pageItems(rows,v.resultPage,size),active=!!(v.resultQuery||v.resultScope!=='all'||v.resultFolder),sourceIds=wrScopeIds(task),legacy=v.resultScope!=='all'&&rows.some(r=>!r.byFile);return '<div class="wr-result-heading"><div class="wr-task-name"><h2 title="'+E(task.name)+'">'+E(task.name||'词云分析结果')+'</h2><span>统计 <strong>'+sourceIds.length+'</strong> 份资料 · '+(active?'匹配':'共')+' <strong>'+all.length+'</strong> 个词</span></div><nav class="wr-view-tabs" aria-label="词云结果视图">'+[['both','词云与词频'],['cloud','词云'],['frequency','词频表']].map(([key,label])=>'<button data-action="aw-view" data-id="'+key+'" aria-pressed="'+(view===key)+'" class="'+(view===key?'active':'')+'">'+label+'</button>').join('')+'</nav></div><div class="wr-filters"><div class="search">'+I('search','icon-sm')+'<input id="aw-result-query" aria-label="搜索分析结果" data-aw-input="result" placeholder="搜索词语" value="'+E(v.resultQuery)+'"></div><label class="wr-scope-label">资料范围<select aria-label="结果文件范围" data-wr-change="scope"><option value="all">全部分析资料</option>'+(task.successIds||task.ids).filter(id=>file(id)&&!file(id).deleted&&auditFileAccess(file(id)).read).map(id=>'<option value="'+E(id)+'" '+(v.resultScope===id?'selected':'')+'>'+E(file(id).name)+'</option>').join('')+'</select></label><label class="wr-top-label">展示前<input type="number" aria-label="结果展示词数" min="10" max="500" data-wr-change="top" value="'+(v.top||task.displayTop||task.config.top)+'">个词</label>'+B('清除筛选','aw-clear','ghost sm',active?'':'disabled')+'</div><div class="wr-top-error" id="wr-top-error" role="alert"></div>'+(rows.length?'<div class="wr-word-body wr-view-'+view+'"><section class="wr-cloud-panel"><header><h3>高频词概览</h3>'+B('下载词云图','aw-cloud-image','ghost sm')+'</header>'+wrCloud(rows)+'<p class="wr-panel-caption">词越大，出现次数越多；点击词语查看来源。</p></section><section class="wr-frequency-panel"><header><h3>词频明细</h3><span>当前展示 <strong>'+rows.length+'</strong> 个词</span></header><div class="aw-table-scroll wr-table-scroll"><table class="table aw-table aw-frequency-table wr-frequency-table"><thead><tr><th>词语</th><th>出现次数</th><th>涉及资料</th><th>下次分析</th></tr></thead><tbody>'+shown.map(r=>'<tr class="'+(v.word===r.word?'wr-active':'')+'"><td><button class="link wr-word-name" data-action="word-detail" data-word="'+E(r.word)+'" title="查看“'+E(r.word)+'”的资料来源">'+E(r.word)+'</button></td><td><strong class="aw-number">'+r.count+'</strong></td><td><button class="link" data-action="word-detail" data-word="'+E(r.word)+'" aria-label="查看 '+E(r.word)+' 的 '+r.docs.length+' 份来源资料">'+r.docs.length+' 份</button></td><td>'+wrStopButton(r.word)+'</td></tr>').join('')+'</tbody></table></div>'+wrPageFooter(v.resultPage,pages,rows.length,'wr-word-page')+'</section></div>':'<div class="wr-no-results">'+awEmpty(task.result?.length?'当前范围没有匹配词语':'本次没有可展示的词语')+'</div>')+'<div class="wr-footnote"><span>'+(legacy?'本次未记录分文件词频，次数为整批统计，仅按来源筛选。':'当前词云、词频表采用相同的资料范围。词频表示出现次数，不代表风险程度。')+'</span>'+A('本次用词','v2-word-selection')+'</div>';};
awToolbar=function(task){const html=wrBase.awToolbar(task);if(!task||task.toolId!=='word'||task.status==='running')return html;const root=document.createElement('div');root.innerHTML=html;root.querySelector('.aw-steps')?.remove();const config=root.querySelector('[data-action=aw-config]');if(config){config.dataset.action='tr-info';config.dataset.id=task.id;config.textContent='任务信息';}const exp=root.querySelector('[data-action=export]');if(exp)exp.textContent='导出数据';return root.innerHTML;};
function wrWordSourceModal(){const p=modalData,t=currentTask(),r=awWordRows(t).find(r=>r.word===p.word)||(t.result||[]).find(r=>r.word===p.word);p.query??='';p.page??=1;const sourceIds=new Set(wrScopeIds(t)),ids=(r?.docs||[]).filter(id=>sourceIds.has(id)),matched=ids.filter(id=>(file(id).name+' '+ewPath(file(id))).toLowerCase().includes(p.query.toLowerCase())),pages=Math.max(1,Math.ceil(matched.length/10));p.page=Math.max(1,Math.min(p.page,pages));const rows=pageItems(matched,p.page,10);return modalFrame('“'+E(p.word)+'”的资料来源','在当前范围内出现 '+(r?.count||0)+' 次，涉及 '+ids.length+' 份资料。','<div class="wr-source-search search">'+I('search','icon-sm')+'<input id="wr-source-query" data-wr-input="source-query" aria-label="查找来源资料" placeholder="查找文件名称或目录" value="'+E(p.query)+'"></div><div class="wr-source-scroll"><table class="table wr-source-table"><thead><tr><th>文件与原文片段</th><th>出现次数</th><th>操作</th></tr></thead><tbody>'+rows.map(id=>{const d=file(id),lines=previewText(d).split('\n').filter(s=>s.includes(p.word)),snippet=(lines[0]||'可打开原文，核对词语所在位置。').slice(0,220);return '<tr><td><strong title="'+E(d.name)+'">'+E(d.name)+'</strong><small>'+E(ewPath(d))+'</small><p title="'+E(snippet)+'">'+E(snippet).split(E(p.word)).join('<mark>'+E(p.word)+'</mark>')+'</p></td><td><strong>'+(r?.byFile?.[id]??'未记录')+'</strong></td><td>'+B('查看原文','aw-review','ghost sm','data-id="'+E(id)+'" data-word="'+E(p.word)+'" '+(auditFileAccess(d).preview?'':'disabled title="暂无预览权限"'))+'</td></tr>';}).join('')+'</tbody></table>'+(!matched.length?'<p class="wc-empty">没有匹配的来源资料。</p>':'')+'</div>'+wrPageFooter(p.page,pages,matched.length,'wr-source-page'),B('关闭','close-modal')+wrStopButton(p.word),'wr-source-dialog aw-word-detail-dialog');}
modalContent=function(){if(modal==='aw-word-detail'&&currentTask()?.toolId==='word')return wrWordSourceModal();return wrBase.modalContent();};
handleAction=function(action,el){if(action==='wr-word-page'){av('word').resultPage+=+el.dataset.step;render();return;}if(action==='wr-source-page'){modalData.page+=+el.dataset.step;paintModal();return;}if(state.toolId==='word'&&action==='aw-clear'){av('word').resultPage=1;}if(state.toolId==='word'&&action==='aw-stop-word'){wrBase.handleAction(action,el);render();if(modal==='aw-word-detail')paintModal();return;}if(['tr-result','tr-config','tr-download'].includes(action)&&modal)closeModal();return wrBase.handleAction(action,el);};
window.addEventListener('change',e=>{const el=e.target,key=el.dataset.wrChange;if(!key||!currentTask()||state.toolId!=='word')return;e.stopImmediatePropagation();const v=av('word');if(key==='top'){const n=Number(el.value),valid=Number.isInteger(n)&&n>=10&&n<=500;el.setAttribute('aria-invalid',String(!valid));const error=document.getElementById('wr-top-error');if(error)error.textContent=valid?'':'请输入 10–500 之间的整数。';if(!valid)return;v.top=n;}else if(key==='scope'){v.resultScope=el.value;v.resultFolder=null;}v.resultPage=1;queueMicrotask(()=>render());},true);
window.addEventListener('input',e=>{const el=e.target;if(el.dataset.wrInput!=='source-query'||modal!=='aw-word-detail')return;const pos=el.selectionStart;modalData.query=el.value;modalData.page=1;paintModal();const next=document.getElementById('wr-source-query');next?.focus();next?.setSelectionRange(pos,pos);},true);
render();
